arguments.command:
cd /testbed && source /opt/miniconda3/bin/activate testbed && python -c "
# Check if there's a mypyc compiled module that might be interfering
import sys
import os

# Check for any __mypyc__ modules
for path in sys.path:
    if os.path.exists(path):
        for item in os.listdir(path):
            if 'mypyc' in item:
                print(f'{path}/{item}')
"

